public class AlkahestryTomeItem extends ChargeableItem {
	public AlkahestryTomeItem() {
		super(new Properties().setNoRepair().rarity(Rarity.EPIC).stacksTo(1).durability(10).component(DataComponents.REPAIR_COST, Integer.MAX_VALUE),
				Config.COMMON.disable.disableAlkahestry);
	}

	@Override
	public int getMaxDamage(ItemStack stack) {
		return getChargeLimit() + 1;
	}

	@Override
	public int getDamage(ItemStack stack) {
		return getMaxDamage(stack) - getCharge(stack);
	}

	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		ItemStack stack = player.getItemInHand(hand);
		ItemStack newStack = super.use(level, player, hand).getObject();
		if (player.isShiftKeyDown()) {
			return new InteractionResultHolder<>(InteractionResult.SUCCESS, newStack);
		}

		player.playSound(ModSounds.BOOK.get(), 1.0f, 1.0f);
		if (!level.isClientSide && player instanceof ServerPlayer serverPlayer) {
			serverPlayer.openMenu(new SimpleMenuProvider((w, p, pl) -> new AlkahestTomeMenu(w), stack.getHoverName()));
		}
		return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
	}

	@Override
	public boolean isEnchantable(ItemStack stack) {
		return false;
	}

	@Override
	public boolean supportsEnchantment(ItemStack stack, Holder<Enchantment> enchantment) {
		return false;
	}

	@Override
	public void inventoryTick(ItemStack tome, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 10 != 0 || !isEnabled(tome)
				|| getCharge(tome) == getChargeLimit()) {
			return;
		}

		for (AlkahestryChargingRecipe recipe : AlkahestryRecipeRegistry.getChargingRecipes()) {
			consumeAndCharge(tome, 0, player, getChargeLimit() - getCharge(tome), recipe.getChargeToAdd(), 16, recipe.getChargingIngredient());
		}
	}

	@Override
	protected boolean isItemValidForContainerSlot(ItemStack containerStack, int slot, ItemStack stack) {
		return slot == 0 && AlkahestryRecipeRegistry.getChargingRecipes().stream().anyMatch(recipe -> recipe.getChargingIngredient().test(stack));
	}

	@Override
	protected void addMoreInformation(ItemStack tome, @Nullable HolderLookup.Provider registries, TooltipBuilder tooltipBuilder) {
		if (registries == null) {
			return;
		}

		tooltipBuilder.charge(this, ".tooltip2", getCharge(tome), getChargeLimit());
		tooltipBuilder.description(this, ".tooltip3");

		if (isEnabled(tome)) {
			tooltipBuilder.absorbActive(AlkahestryRecipeRegistry.getDrainRecipe().map(r -> r.getResultItem(registries).getHoverName().getString()).orElse(""));
		} else {
			tooltipBuilder.absorb();
		}
	}

	@Override
	protected boolean hasMoreInformation(ItemStack stack) {
		return true;
	}

	public static int getChargeLimit() {
		return Config.getOrDefault(Config.COMMON.items.alkahestryTome.chargeLimit, Config.COMMON_SPEC);
	}

	public static ItemStack setCharge(ItemStack tome, int charge) {
		tome.set(ModDataComponents.CHARGE, charge);
		return tome;
	}

	public static int getCharge(ItemStack tome) {
		return ModItems.ALKAHESTRY_TOME.get().getStoredCharge(tome, 0);
	}

	public static void addCharge(ItemStack tome, int chargeToAdd) {
		ModItems.ALKAHESTRY_TOME.get().addStoredCharge(tome, 0, chargeToAdd, null);
	}

	@Override
	public int getStoredCharge(ItemStack tome, int slot) {
		return tome.getOrDefault(ModDataComponents.CHARGE, 0);
	}

	@Override
	public void addStoredCharge(ItemStack tome, int slot, int chageToAdd, @Nullable ItemStack chargeStack) {
		setCharge(tome, getStoredCharge(tome, slot) + chageToAdd);
	}
}

package reliquary.item;

import com.google.common.collect.ImmutableMap;
import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.DynamicOps;
import com.mojang.serialization.codecs.PrimitiveCodec;
import net.minecraft.network.FriendlyByteBuf;
import net.minecraft.network.codec.ByteBufCodecs;
import net.minecraft.network.codec.StreamCodec;
import net.minecraft.util.ExtraCodecs;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import reliquary.init.ModDataComponents;
import reliquary.item.component.OversizedComponentItemHandler;
import reliquary.util.InventoryHelper;

import javax.annotation.Nullable;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.Supplier;

public abstract class ChargeableItem extends ToggleableItem {
	public static final PrimitiveCodec<Integer> STRING_ENCODED_INT = new PrimitiveCodec<>() {
		@Override
		public <T> DataResult<Integer> read(final DynamicOps<T> ops, final T input) {
			return ops.getStringValue(input).map(s -> {
				if (s.startsWith("i")) {
					return Integer.parseInt(s.substring(1));
				} else {
					return Integer.parseInt(s);
				}
			});
		}

		@Override
		public <T> T write(final DynamicOps<T> ops, final Integer value) {
			return ops.createString("i" + value);
		}

		@Override
		public String toString() {
			return "Int";
		}
	};

	public static final Codec<Map<Integer, Integer>> PARTIAL_CHARGES_CODEC = Codec.unboundedMap(STRING_ENCODED_INT, ExtraCodecs.NON_NEGATIVE_INT);
	private static final int MAX_PARTIAL_CHARGES = 64;

	public static final StreamCodec<FriendlyByteBuf, Map<Integer, Integer>> PARTIAL_CHARGES_STREAM_CODEC = ByteBufCodecs.map(HashMap::new, ByteBufCodecs.INT,
			ByteBufCodecs.INT, MAX_PARTIAL_CHARGES);

	protected static final int FIRST_SLOT = 0;

	protected ChargeableItem(Properties properties, Supplier<Boolean> isDisabled) {
		super(properties, isDisabled);
	}

	protected ChargeableItem(Properties properties) {
		this(properties, () -> false);
	}

	protected <T> T getFromHandler(ItemStack stack, Function<OversizedComponentItemHandler, T> getter) {
		return getter.apply(createHandler(stack));
	}

	protected void runOnHandler(ItemStack stack, Consumer<OversizedComponentItemHandler> runner) {
		runner.accept(createHandler(stack));
	}

	public OversizedComponentItemHandler createHandler(ItemStack containerStack) {
		int size = Math.max(containerStack.has(ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS)
				? containerStack.get(ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS).getSlots()
				: getContainerInitialSize(), getContainerInitialSize());
		return new OversizedComponentItemHandler(containerStack, ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS.get(), size, this::getContainerSlotLimit,
				(slot, stack) -> isItemValidForContainerSlot(containerStack, slot, stack));
	}

	protected int getSlotWorth(int slot) {
		return 1;
	}

	protected void removeContainerContents(ItemStack stack) {
		stack.remove(ModDataComponents.OVERSIZED_ITEM_CONTAINER_CONTENTS);
	}

	protected int getContainerInitialSize() {
		return 1;
	}

	protected int getContainerSlotLimit(ItemStack stack, int slot) {
		return getContainerSlotLimit(slot);
	}

	protected int getContainerSlotLimit(int slot) {
		return 64;
	}

	protected abstract boolean isItemValidForContainerSlot(ItemStack containerStack, int slot, ItemStack stack);

	protected void consumeAndCharge(ItemStack containerStack, int slot, Player player, int freeCapacity, int chargePerItem, int maxCount) {
		Predicate<ItemStack> isValidStack = stack -> isItemValidForContainerSlot(containerStack, slot, stack);
		consumeAndCharge(containerStack, slot, player, freeCapacity, chargePerItem, maxCount, isValidStack);
	}

	protected void consumeAndCharge(ItemStack containerStack, int slot, Player player, int freeCapacity, int chargePerItem, int maxCount,
			Predicate<ItemStack> itemMatches) {
		int maximumToConsume = Math.min(freeCapacity / chargePerItem, maxCount);
		if (maximumToConsume == 0) {
			return;
		}
		ItemStack consumedStack = InventoryHelper.consumeItemStack(itemMatches, player, maximumToConsume);
		if (consumedStack.getCount() > 0) {
			addStoredCharge(containerStack, slot, consumedStack.getCount() * chargePerItem, consumedStack);
			if (!containerStack.has(ModDataComponents.PARTIAL_CHARGES)) {
				HashMap<Integer, Integer> charges = new HashMap<>();
				charges.put(slot, 0);
				setPartialCharges(containerStack, charges);
			}
		}
	}

	private int getPartialCharge(ItemStack containerStack, int slot) {
		Map<Integer, Integer> charges = containerStack.get(ModDataComponents.PARTIAL_CHARGES);
		if (charges != null) {
			return charges.getOrDefault(slot, 0);
		}
		return 0;
	}

	public int getTotalCharge(ItemStack containerStack) {
		return getTotalCharge(containerStack, FIRST_SLOT);
	}

	public int getTotalCharge(ItemStack containerStack, int slot) {
		long totalCharge = (long) getMigratedStoredCharge(containerStack, slot) * getSlotWorth(slot) + getPartialCharge(containerStack, slot);
		return (int) Math.min(totalCharge, Integer.MAX_VALUE);
	}

	private void setPartialCharge(ItemStack containerStack, int slot, int charge) {
		Map<Integer, Integer> charges = containerStack.get(ModDataComponents.PARTIAL_CHARGES);
		charges = charges != null ? new HashMap<>(charges) : new HashMap<>();
		charges.put(slot, charge);
		setPartialCharges(containerStack, charges);
	}

	private void removePartialCharge(ItemStack containerStack, int slot) {
		Map<Integer, Integer> charges = containerStack.get(ModDataComponents.PARTIAL_CHARGES);
		if (charges != null && charges.containsKey(slot)) {
			charges = new HashMap<>(charges);
			charges.remove(slot);
			setPartialCharges(containerStack, charges);
		}
	}

	protected boolean addPartialCharge(ItemStack containerStack, int slot, int chargeToAdd, int pointLimit, ItemStack chargeStack) {
		int worth = getSlotWorth(slot);
		int storedCharge = getMigratedStoredCharge(containerStack, slot);
		int currentCharge = getPartialCharge(containerStack, slot);
		long totalCharge = (long) storedCharge * worth + currentCharge;
		int remainingCapacity = Math.toIntExact(Math.max(pointLimit - totalCharge, 0));
		int acceptedCharge = Math.min(Math.max(chargeToAdd, 0), remainingCapacity);
		int updatedPartialCharge = currentCharge + acceptedCharge;
		if (updatedPartialCharge >= worth) {
			int maxPhysicalCharge = pointLimit / worth;
			int fullCharges = Math.min(updatedPartialCharge / worth, Math.max(maxPhysicalCharge - storedCharge, 0));
			if (fullCharges > 0) {
				ItemStack storedChargeStack = chargeStack.copy();
				storedChargeStack.setCount(fullCharges);
				addStoredCharge(containerStack, slot, fullCharges, storedChargeStack);
				updatedPartialCharge -= fullCharges * worth;
			}
		}
		setPartialCharge(containerStack, slot, updatedPartialCharge);
		return acceptedCharge > 0;
	}

	private void setPartialCharges(ItemStack containerStack, Map<Integer, Integer> charges) {
		containerStack.set(ModDataComponents.PARTIAL_CHARGES, ImmutableMap.copyOf(charges));
	}

	public abstract void addStoredCharge(ItemStack containerStack, int slot, int chargeToAdd, @Nullable ItemStack chargeStack);

	protected void extractStoredCharge(ItemStack containerStack, int slot, int chargeToExtract) {
		addStoredCharge(containerStack, slot, -chargeToExtract, null);
	}

	protected int getMigratedStoredCharge(ItemStack containerStack, int slot) {
		if (!containerStack.has(ModDataComponents.PARTIAL_CHARGES)) {
			migrateLegacyChargeData(containerStack);
		}

		return getStoredCharge(containerStack, slot);
	}

	public abstract int getStoredCharge(ItemStack containerStack, int slot);

	protected boolean removeSlotWhenEmpty(int slot) {
		return false;
	}

	protected void removeSlot(ItemStack containerStack, int slot) {
		// noop
	}

	private void migrateLegacyChargeData(ItemStack containerStack) {
		Map<Integer, Integer> charges = new HashMap<>();
		int slots = createHandler(containerStack).getSlots();
		for (int slot = 0; slot < slots; slot++) {
			int worth = getSlotWorth(slot);
			int storedCharge = getStoredCharge(containerStack, slot);
			if (storedCharge <= 0 || worth <= 1) {
				continue;
			}

			int physicalCharge = storedCharge / worth;
			extractStoredCharge(containerStack, slot, storedCharge - physicalCharge);
			int partialCharge = storedCharge % worth;
			if (partialCharge > 0) {
				charges.put(slot, partialCharge);
			}
		}
		setPartialCharges(containerStack, charges);
	}

	public boolean useCharge(ItemStack containerStack, int chargeToUse) {
		return useCharge(containerStack, FIRST_SLOT, chargeToUse);
	}

	public boolean useCharge(ItemStack containerStack, int slot, int chargeToUse) {
		int charge = getMigratedStoredCharge(containerStack, slot);
		int partialCharge = getPartialCharge(containerStack, slot);

		if (partialCharge >= chargeToUse) {
			if (partialCharge == chargeToUse) {
				removePartialCharge(containerStack, slot);
			} else {
				setPartialCharge(containerStack, slot, partialCharge - chargeToUse);
			}
			return true;
		}

		int worth = getSlotWorth(slot);

		if ((long) charge * worth + partialCharge >= chargeToUse) {
			long additionalPartialChargeNeeded = (long) chargeToUse - partialCharge;
			int actualChargeToRemove = (int) (additionalPartialChargeNeeded / worth + (additionalPartialChargeNeeded % worth > 0 ? 1 : 0));
			int partialChargeToAdd = (int) ((long) actualChargeToRemove * worth - chargeToUse);
			if (actualChargeToRemove == charge && removeSlotWhenEmpty(slot)) {
				removeSlot(containerStack, slot);
			} else {
				extractStoredCharge(containerStack, slot, actualChargeToRemove);
			}

			int newPartialCharge = partialCharge + partialChargeToAdd;
			if (newPartialCharge > 0) {
				setPartialCharge(containerStack, slot, newPartialCharge);
			} else {
				removePartialCharge(containerStack, slot);
			}
			return true;
		}

		return false;
	}

	protected boolean addItemToContainer(ItemStack container, Item item, int chargeToAdd) {
		ItemStack stack = new ItemStack(item);
		stack.setCount(chargeToAdd);
		return getFromHandler(container, handler -> handler.insertItemOrAddIntoNewSlotIfNoStackMatches(stack)).isEmpty();
	}

	public boolean removeItemFromInternalStorage(ItemStack stack, int slot, int quantityToRemove, boolean simulate, Player player) {
		if (player.isCreative()) {
			return true;
		}

		return getFromHandler(stack, handler -> handler.extractItemAndRemoveSlotIfEmpty(slot, quantityToRemove, simulate)).getCount() == quantityToRemove;
	}
}

package reliquary.item;

import net.minecraft.ChatFormatting;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Holder;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.NonNullList;
import net.minecraft.network.chat.Component;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.ExperienceOrb;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Rarity;
import net.minecraft.world.item.UseAnim;
import net.minecraft.world.item.enchantment.Enchantment;
import net.minecraft.world.item.enchantment.EnchantmentEffectComponents;
import net.minecraft.world.item.enchantment.ItemEnchantments;
import net.minecraft.world.level.ClipContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.neoforged.neoforge.items.IItemHandler;
import reliquary.Reliquary;
import reliquary.api.IPedestal;
import reliquary.api.IPedestalActionItem;
import reliquary.init.ModDataComponents;
import reliquary.item.util.ICuriosItem;
import reliquary.item.util.IScrollableItem;
import reliquary.reference.Config;
import reliquary.util.InventoryHelper;
import reliquary.util.PlayerInventoryProvider;
import reliquary.util.TooltipBuilder;
import reliquary.util.XpHelper;

import javax.annotation.Nullable;

import java.util.List;

public class HeroMedallionItem extends ToggleableItem implements IPedestalActionItem, IScrollableItem, ICuriosItem {
	public HeroMedallionItem() {
		super(new Properties().durability(0).setNoRepair().rarity(Rarity.EPIC));
	}

	@Override
	public boolean isFoil(ItemStack stack) {
		return stack.getOrDefault(ModDataComponents.ENABLED, false);
	}

	@Override
	public UseAnim getUseAnimation(ItemStack stack) {
		return UseAnim.BLOCK;
	}

	@Override
	protected void addMoreInformation(ItemStack medallion, @Nullable HolderLookup.Provider registries, TooltipBuilder tooltipBuilder) {
		int experience = getExperience(medallion);
		int levels = XpHelper.getLevelForExperience(experience);
		int remainingExperience = experience - XpHelper.getExperienceForLevel(levels);
		tooltipBuilder.data(this, ".tooltip2", levels, remainingExperience);
		tooltipBuilder.description(this, ".tooltip.drain_levels", Component.literal(String.valueOf(getDrainXpLevels(medallion))).withStyle(ChatFormatting.RED));
		if (isEnabled(medallion)) {
			tooltipBuilder.absorbActive(Component.translatable("tooltip.reliquary.xp").withStyle(ChatFormatting.GREEN));
			tooltipBuilder.description(this, ".tooltip.fill_stop_level",
					Component.literal(String.valueOf(getStopAtXpLevel(medallion))).withStyle(ChatFormatting.GREEN));
		} else {
			tooltipBuilder.absorb();
		}
		tooltipBuilder.description(this, ".tooltip.scroll_to_change");
	}

	@Override
	protected boolean hasMoreInformation(ItemStack stack) {
		return true;
	}

	@Override
	public void inventoryTick(ItemStack stack, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || !isEnabled(stack) || level.getGameTime() % 10 != 0) {
			return;
		}
		if ((!player.isUsingItem() || player.getUseItem() != stack)) {
			drainExperienceLevel(stack, player);
		}

		repairItemsInPlayersInventory(stack, player);
	}

	private void repairItemsInPlayersInventory(ItemStack heroMedallion, Player player) {
		long cooldownTime = heroMedallion.getOrDefault(ModDataComponents.COOLDOWN_TIME, 0L);
		if (cooldownTime > player.level().getGameTime()) {
			return;
		}
		heroMedallion.set(ModDataComponents.COOLDOWN_TIME, player.level().getGameTime() + Config.COMMON.items.heroMedallion.repairCoolDown.get());

		PlayerInventoryProvider.get().runOnPlayerInventoryHandlers(player, stack -> {
			if (canRepairWithXp(stack)) {
				repairItemWithXp(heroMedallion, stack);
			}
		});
	}

	private void drainExperienceLevel(ItemStack stack, Player player) {
		int totalPlayerExperience = XpHelper.getTotalPlayerExperience(player);
		int previousPlayerLevel = XpHelper.getLevelForExperience(totalPlayerExperience) - 1; // calculating this so that player levels over 21483 don't break
																								// the math
		int experiencePoints = player.isCreative()
				? 100
				: totalPlayerExperience - XpHelper.getExperienceForLevel(Math.max(getStopAtXpLevel(stack), previousPlayerLevel));
		experiencePoints = Math.min(experiencePoints, Integer.MAX_VALUE - getExperience(stack));
		if (experiencePoints > 0) {
			if (!player.isCreative()) {
				decreasePlayerExperience(player, experiencePoints);
			}
			increaseMedallionExperience(stack, experiencePoints);
		}
	}

	private void decreasePlayerExperience(Player player, int pointsToRemove) {
		player.giveExperiencePoints(-pointsToRemove);
	}

	private void decreaseMedallionExperience(ItemStack stack, int experience) {
		setExperience(stack, getExperience(stack) - experience);
	}

	private void increasePlayerExperience(Player player, int xpPoints) {
		player.giveExperiencePoints(xpPoints);
	}

	private void increaseMedallionExperience(ItemStack stack, int xpPoints) {
		setExperience(stack, getExperience(stack) + xpPoints);
	}

	public int getExperience(ItemStack stack) {
		return stack.getOrDefault(ModDataComponents.EXPERIENCE, 0);
	}

	public void setExperience(ItemStack stack, int experience) {
		stack.set(ModDataComponents.EXPERIENCE, experience);
	}

	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		ItemStack stack = player.getItemInHand(hand);
		if (level.isClientSide) {
			return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
		}
		if (player.isShiftKeyDown()) {
			return super.use(level, player, hand);
		}

		drainExperience(stack, player, level, getDrainXpLevels(stack));

		return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
	}

	private void drainExperience(ItemStack stack, Player player, Level level, int xpLevels) {
		BlockHitResult rayTraceResult = getPlayerPOVHitResult(level, player, ClipContext.Fluid.ANY);

		if (rayTraceResult.getType() == HitResult.Type.BLOCK) {
			BlockPos hitPos = rayTraceResult.getBlockPos().offset(rayTraceResult.getDirection().getNormal());
			spawnXpOnGround(stack, level, hitPos, xpLevels);
		} else {
			xpLevels += Math.round(player.experienceProgress);

			while (xpLevels > 0) {
				int xp = Math.max(0, (int) ((1 - player.experienceProgress) * XpHelper.getExperienceLimitOnLevel(player.experienceLevel)) + 1);
				int pointsToAdd = player.isCreative() ? xp : Math.min(xp, getExperience(stack));
				player.giveExperiencePoints(pointsToAdd);
				if (!player.isCreative()) {
					decreaseMedallionExperience(stack, pointsToAdd);
				}
				xpLevels--;
			}
		}
	}

	@Override
	public void releaseUsing(ItemStack stack, Level level, LivingEntity livingEntity, int timeLeft) {
		if (livingEntity.level().isClientSide || isEnabled(stack) || !(livingEntity instanceof Player) || getUseDuration(stack, livingEntity) - timeLeft > 10) {
			return;
		}

		drainExperience(stack, (Player) livingEntity, livingEntity.level(), 1);
	}

	private void spawnXpOnGround(ItemStack stack, Level level, BlockPos hitPos, int xpLevels) {
		int xp = XpHelper.getExperienceForLevel(xpLevels);

		if (getExperience(stack) >= xp) {
			decreaseMedallionExperience(stack, xp);

			while (xp > 0) {
				int j = ExperienceOrb.getExperienceValue(xp);
				xp -= j;
				level.addFreshEntity(new ExperienceOrb(level, hitPos.getX(), hitPos.getY(), hitPos.getZ(), j));
			}
		}
	}

	@Override
	public void update(ItemStack stack, Level level, IPedestal pedestal) {
		List<BlockPos> posInRange = pedestal.getPedestalsInRange(level, Config.COMMON.items.heroMedallion.pedestalRange.get());
		for (BlockPos pedestalPos : posInRange) {
			InventoryHelper.runOnInventoryAt(level, pedestalPos, pedestalInventory -> repairItemsWithXp(stack, pedestalInventory));
		}
		pedestal.setActionCoolDown(Config.COMMON.items.heroMedallion.repairCoolDown.get());
	}

	private void repairItemsWithXp(ItemStack stack, IItemHandler inventory) {
		for (ItemStack itemToRepair : getItemsRepairedWithXp(inventory)) {
			repairItemWithXp(stack, itemToRepair);
		}
	}

	private void repairItemWithXp(ItemStack heroMedallion, ItemStack itemToRepair) {
		int xpToRepair = Math.min(Config.COMMON.items.heroMedallion.repairStepXP.get(), getExperience(heroMedallion));
		int durabilityToRepair = Math.min(XpHelper.xpToDurability(xpToRepair), itemToRepair.getDamageValue());

		setExperience(heroMedallion, getExperience(heroMedallion) - XpHelper.durabilityToXp(durabilityToRepair));
		itemToRepair.setDamageValue(itemToRepair.getDamageValue() - durabilityToRepair);
	}

	private List<ItemStack> getItemsRepairedWithXp(IItemHandler inventory) {
		NonNullList<ItemStack> stacksToReturn = NonNullList.create();

		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			ItemStack stack = inventory.getStackInSlot(slot);
			// only getting items that are more than 1 damaged to not waste xp
			if (canRepairWithXp(stack)) {
				stacksToReturn.add(stack);
			}
		}
		return stacksToReturn;
	}

	private boolean canRepairWithXp(ItemStack stack) {
		if (stack.isDamaged() && stack.getDamageValue() > 1) {
			ItemEnchantments itemenchantments = stack.getTagEnchantments();

			for (Holder<Enchantment> enchantment : itemenchantments.keySet()) {
				if (enchantment.value().effects().has(EnchantmentEffectComponents.REPAIR_WITH_XP)) {
					return true;
				}
			}

		}
		return false;
	}

	@Override
	public void onRemoved(ItemStack stack, Level level, IPedestal pedestal) {
		// nothing needed
	}

	@Override
	public void stop(ItemStack stack, Level level, IPedestal pedestal) {
		// nothing needed
	}

	@Override
	public InteractionResult onMouseScrolled(ItemStack stack, Player player, double scrollDelta) {
		if (player.level().isClientSide) {
			return InteractionResult.PASS;
		}

		int levelAddition = scrollDelta > 0 ? 1 : -1;
		if (isEnabled(stack)) {
			int newLevels = Math.max(0, getStopAtXpLevel(stack) + levelAddition);
			setStopAtXpLevel(stack, newLevels);
			player.displayClientMessage(Component.translatable("chat." + Reliquary.MOD_ID + ".hero_medallion.fill_levels",
					Component.literal(String.valueOf(newLevels)).withStyle(ChatFormatting.GREEN)), true);
		} else {
			int newLevels = Math.max(1, getDrainXpLevels(stack) + levelAddition);
			setDrainXpLevels(stack, newLevels);
			player.displayClientMessage(Component.translatable("chat." + Reliquary.MOD_ID + ".hero_medallion.drain_levels",
					Component.literal(String.valueOf(newLevels)).withStyle(ChatFormatting.RED)), true);
		}

		return InteractionResult.SUCCESS;
	}

	private int getDrainXpLevels(ItemStack stack) {
		return stack.getOrDefault(ModDataComponents.DRAIN_XP_LEVELS, 1);
	}

	private int getStopAtXpLevel(ItemStack stack) {
		return stack.getOrDefault(ModDataComponents.STOP_AT_XP_LEVEL, 0);
	}

	private void setDrainXpLevels(ItemStack stack, int levels) {
		stack.set(ModDataComponents.DRAIN_XP_LEVELS, levels);
	}

	private void setStopAtXpLevel(ItemStack stack, int levels) {
		stack.set(ModDataComponents.STOP_AT_XP_LEVEL, levels);
	}

	@Override
	public Type getCuriosType() {
		return Type.NECKLACE;
	}

	@Override
	public void onWornTick(ItemStack stack, LivingEntity player) {
		inventoryTick(stack, player.level(), player, 0, false);
	}
}

package reliquary.item;

import net.minecraft.core.BlockPos;
