import net.neoforged.neoforge.fluids.capability.IFluidHandler;
import net.neoforged.neoforge.fluids.capability.IFluidHandlerItem;
import reliquary.handler.CommonEventHandler;
import reliquary.handler.HandlerPriority;
import reliquary.handler.IPlayerHurtHandler;
import reliquary.init.ModDataComponents;
import reliquary.init.ModItems;
import reliquary.reference.Config;
import reliquary.util.InventoryHelper;
import reliquary.util.TooltipBuilder;

import javax.annotation.Nullable;

public class InfernalChaliceItem extends ToggleableItem {
	public InfernalChaliceItem() {
		super(new Properties().stacksTo(1).setNoRepair());

		CommonEventHandler.registerPlayerHurtHandler(new IPlayerHurtHandler() {
			@Override
			public boolean canApply(Player player, LivingIncomingDamageEvent event) {
				return (event.getSource().is(DamageTypeTags.IS_FIRE)) && player.getFoodData().getFoodLevel() > 0
						&& InventoryHelper.playerHasItem(player, ModItems.INFERNAL_CHALICE.get());
			}

			@Override
			public boolean apply(Player player, LivingIncomingDamageEvent event) {
				player.causeFoodExhaustion(event.getAmount() * ((float) Config.COMMON.items.infernalChalice.hungerCostPercent.get() / 100F));
				return true;
			}

			@Override
			public HandlerPriority getPriority() {
				return HandlerPriority.HIGH;
			}
		});
	}

	@Override
	protected void addMoreInformation(ItemStack chalice, @Nullable HolderLookup.Provider registries, TooltipBuilder tooltipBuilder) {
		tooltipBuilder.charge(this, ".tooltip2", chalice.getOrDefault(ModDataComponents.FLUID_CONTENTS, SimpleFluidContent.EMPTY).getAmount());
		if (isEnabled(chalice)) {
			tooltipBuilder.description("tooltip.reliquary.place");
		} else {
			tooltipBuilder.description("tooltip.reliquary.drain");
		}
	}

	@Override
	protected boolean hasMoreInformation(ItemStack stack) {
		return true;
	}

	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		ItemStack stack = player.getItemInHand(hand);
		if (player.isShiftKeyDown()) {
			return super.use(level, player, hand);
		}

		BlockHitResult result = getPlayerPOVHitResult(level, player, isEnabled(stack) ? ClipContext.Fluid.SOURCE_ONLY : ClipContext.Fluid.NONE);

		if (result.getType() != HitResult.Type.BLOCK) {
			return new InteractionResultHolder<>(InteractionResult.PASS, stack);
		} else {
			BlockPos pos = result.getBlockPos();
			if (!level.mayInteract(player, pos)) {
				return new InteractionResultHolder<>(InteractionResult.PASS, stack);
			}

			Direction face = result.getDirection();
			if (!player.mayUseItemAt(pos, face, stack)) {
				return new InteractionResultHolder<>(InteractionResult.PASS, stack);
			}

			IFluidHandlerItem fluidHandler = stack.getCapability(Capabilities.FluidHandler.ITEM);
			if (fluidHandler == null) {
				return new InteractionResultHolder<>(InteractionResult.FAIL, stack);
			}

			return interactWithFluidHandler(level, player, stack, pos, face, fluidHandler);
		}
	}

	private InteractionResultHolder<ItemStack> interactWithFluidHandler(Level level, Player player, ItemStack stack, BlockPos pos, Direction face,
			IFluidHandlerItem fluidHandler) {
		BlockState blockState = level.getBlockState(pos);
		if (isEnabled(stack)) {
			if (blockState.getBlock() == Blocks.LAVA && blockState.getValue(LiquidBlock.LEVEL) == 0
					&& fluidHandler.fill(new FluidStack(Fluids.LAVA, FluidType.BUCKET_VOLUME), IFluidHandler.FluidAction.SIMULATE) == FluidType.BUCKET_VOLUME) {
				level.setBlockAndUpdate(pos, Blocks.AIR.defaultBlockState());
				Fluids.LAVA.getPickupSound().ifPresent(soundEvent -> level.playSound(player, pos, soundEvent, SoundSource.BLOCKS, 1.0F, 1.0F));
				fluidHandler.fill(new FluidStack(Fluids.LAVA, FluidType.BUCKET_VOLUME), IFluidHandler.FluidAction.EXECUTE);
				return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
			}
		} else {
			FluidStack fluidDrained = fluidHandler.drain(new FluidStack(Fluids.LAVA, FluidType.BUCKET_VOLUME), IFluidHandler.FluidAction.SIMULATE);
			if (player.isCreative() || fluidDrained.getAmount() == FluidType.BUCKET_VOLUME) {
				BlockPos adjustedPos = pos.relative(face);
				if (tryPlaceContainedLiquid(player, level, adjustedPos) && !player.isCreative()) {
					fluidHandler.drain(new FluidStack(Fluids.LAVA, FluidType.BUCKET_VOLUME), IFluidHandler.FluidAction.EXECUTE);
					return new InteractionResultHolder<>(InteractionResult.SUCCESS, stack);
				}
			}
		}
		return new InteractionResultHolder<>(InteractionResult.PASS, stack);
	}

	private boolean tryPlaceContainedLiquid(Player player, Level level, BlockPos pos) {
		BlockState blockState = level.getBlockState(pos);
		if (!blockState.canBeReplaced(Fluids.LAVA)) {
			return false;
		} else {
			level.setBlock(pos, Blocks.LAVA.defaultBlockState(), 3);
			level.playSound(player, pos, SoundEvents.BUCKET_EMPTY_LAVA, SoundSource.BLOCKS, 1, 1);
			return true;
		}
	}

	public static int getFluidBucketAmount(ItemStack stack) {
		IFluidHandlerItem fluidHandler = stack.getCapability(Capabilities.FluidHandler.ITEM);
		return fluidHandler != null ? fluidHandler.getFluidInTank(0).getAmount() / FluidType.BUCKET_VOLUME : 0;
	}
}

package reliquary.item;

import net.minecraft.ChatFormatting;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.MutableComponent;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Rarity;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.item.component.ItemContainerContents;
import net.minecraft.world.level.Level;
import net.neoforged.neoforge.items.IItemHandler;
import reliquary.Reliquary;
import reliquary.crafting.InfernalTearValueHelper;
import reliquary.init.ModDataComponents;
import reliquary.reference.Config;
import reliquary.util.InventoryHelper;
import reliquary.util.TooltipBuilder;

import javax.annotation.Nullable;

import java.util.List;
import java.util.Map;
import java.util.Optional;

public class InfernalTearItem extends ToggleableItem {
	private static final int COOLDOWN = 4;
	private static final int NOTHING_FOUND_COOLDOWN = COOLDOWN * 5;

	public InfernalTearItem() {
		super(new Properties().stacksTo(1).setNoRepair().rarity(Rarity.EPIC));
	}

	@Override
	public MutableComponent getName(ItemStack stack) {
		return super.getName(stack).withStyle(ChatFormatting.RED);
	}

	@Override
	public void inventoryTick(ItemStack tear, Level level, Entity entity, int itemSlot, boolean isSelected) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % COOLDOWN != 0 || !isEnabled(tear)
				|| isInCooldown(tear, level)) {
			return;
		}

		ItemStack tearStack = getStackFromTear(tear);
		if (tearStack.isEmpty()) {
			resetTear(tear);
			return;
		}

		Optional<Integer> experience = InfernalTearValueHelper.getItemExperience(level, tearStack.getItem());
		if (experience.isEmpty()) {
			resetTear(tear);
			return;
		}

		int countConsumed = InventoryHelper.consumeItemStack(stack -> ItemStack.isSameItemSameComponents(tearStack, stack), player, 4).getCount();
		if (countConsumed > 0) {
			player.giveExperiencePoints(experience.get() * countConsumed);
		} else {
			setCooldown(tear, level, NOTHING_FOUND_COOLDOWN);
		}
	}

	private void resetTear(ItemStack stack) {
		stack.remove(DataComponents.CONTAINER);
		stack.remove(ModDataComponents.ENABLED);
	}

	@Override
	public void appendHoverText(ItemStack stack, TooltipContext context, List<Component> tooltip, TooltipFlag flag) {
		super.appendHoverText(stack, context, tooltip, flag);
		if (getStackFromTear(stack).isEmpty()) {
			TooltipBuilder.of(tooltip, context).description("tooltip.reliquary.tear_empty");
		}
	}

	@Override
	protected void addMoreInformation(ItemStack stack, @Nullable HolderLookup.Provider registries, TooltipBuilder tooltipBuilder) {
		ItemStack contents = getStackFromTear(stack);
		String itemName = contents.getHoverName().getString();

		tooltipBuilder.data("tooltip." + Reliquary.MOD_ID + ".tear", itemName);

		if (isEnabled(stack)) {
			tooltipBuilder.absorbActive(itemName);
		}
		tooltipBuilder.description("tooltip." + Reliquary.MOD_ID + ".absorb");
		tooltipBuilder.description(this, ".infernal_tear.absorb_unset");
	}

	@Override
	protected boolean hasMoreInformation(ItemStack stack) {
		return !getStackFromTear(stack).isEmpty();
	}

	public static ItemStack getStackFromTear(ItemStack tear) {
		ItemContainerContents contents = tear.getOrDefault(DataComponents.CONTAINER, ItemContainerContents.EMPTY);
		return contents.getSlots() > 0 ? contents.getStackInSlot(0) : ItemStack.EMPTY;
	}

	@Override
	public InteractionResultHolder<ItemStack> use(Level level, Player player, InteractionHand hand) {
		if (level.isClientSide()) {
			return new InteractionResultHolder<>(InteractionResult.SUCCESS, player.getItemInHand(hand));
		}
		InteractionResultHolder<ItemStack> actionResult = super.use(level, player, hand);
		ItemStack tear = actionResult.getObject();
		if (player.isShiftKeyDown() && !isEnabled(tear)) {
			return actionResult;
		}

		// empty the tear if player is not sneaking and the tear is not empty
		if (!player.isShiftKeyDown() && !getStackFromTear(tear).isEmpty()) {
			resetTear(tear);
			return actionResult;
		}

		// nothing more to do with a filled tear here
		if (!getStackFromTear(tear).isEmpty()) {
			return actionResult;
		}

		// if user is sneaking or just enabled the tear, let's fill it
		if (player.isShiftKeyDown() || !isEnabled(tear)) {
			IItemHandler playerInventory = InventoryHelper.getMainInventoryItemHandlerFrom(player);
			ItemStack returnStack = buildTear(tear, playerInventory, player.level());
			if (!returnStack.isEmpty()) {
				return new InteractionResultHolder<>(InteractionResult.SUCCESS, returnStack);
			}
		}

		// by this time the tear is still empty and there wasn't anything to put in it
		// so let's disable it if it got enabled
		if (isEnabled(tear)) {
			toggleEnabled(tear);
		}
		return actionResult;
	}

	private ItemStack buildTear(ItemStack stack, IItemHandler inventory, Level level) {
		ItemStack tear = new ItemStack(this, 1);

		ItemStack target = getTargetAlkahestItem(stack, inventory, level);
		if (target.isEmpty()) {
			return ItemStack.EMPTY;
		}

		setTearTarget(tear, target);

		if (Boolean.TRUE.equals(Config.COMMON.items.infernalTear.absorbWhenCreated.get())) {
			stack.set(ModDataComponents.ENABLED, true);
		}

		return tear;
	}

	public static void setTearTarget(ItemStack tear, ItemStack target) {
		tear.set(DataComponents.CONTAINER, ItemContainerContents.fromItems(List.of(target)));
	}

	private ItemStack getTargetAlkahestItem(ItemStack self, IItemHandler inventory, Level level) {
		ItemStack targetItem = ItemStack.EMPTY;
		int itemQuantity = 0;
		Map<Item, Integer> itemExperiences = InfernalTearValueHelper.getItemExperiences(level);
		for (int slot = 0; slot < inventory.getSlots(); slot++) {
			ItemStack stack = inventory.getStackInSlot(slot);
			if (stack.isEmpty() || self.getItem() == stack.getItem() || stack.getMaxStackSize() == 1 || !stack.getComponentsPatch().isEmpty()
					|| !itemExperiences.containsKey(stack.getItem())) {
				continue;
			}
			if (InventoryHelper.getItemQuantity(stack, inventory) > itemQuantity) {
				itemQuantity = InventoryHelper.getItemQuantity(stack, inventory);
				targetItem = stack.copy();
			}
		}
		return targetItem;
	}
}

package reliquary.item;

import com.google.common.collect.ImmutableMap;
import net.minecraft.core.Holder;
import net.minecraft.core.HolderLookup;
import net.minecraft.core.component.DataComponents;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.level.Level;
import net.neoforged.neoforge.items.IItemHandler;
import reliquary.init.ModDataComponents;
import reliquary.item.util.ICuriosItem;
import reliquary.reference.Config;
import reliquary.util.InventoryHelper;
import reliquary.util.RegistryHelper;
import reliquary.util.TooltipBuilder;

import javax.annotation.Nullable;

import java.util.List;
import java.util.Map;
import java.util.Optional;

public class MidasTouchstoneItem extends ChargeableItem implements ICuriosItem {
	private static final Map<Class<? extends Item>, IRepairableItem> REPAIRABLE_ITEMS = new ImmutableMap.Builder<Class<? extends Item>, IRepairableItem>()
			.put(TieredItem.class, item -> {
				Tier tier = ((TieredItem) item).getTier();
				return tier.equals(Tiers.GOLD) || tier.equals(Tiers.NETHERITE);
			}).put(ArmorItem.class, item -> {
				Holder<ArmorMaterial> material = ((ArmorItem) item).getMaterial();
				return material.equals(ArmorMaterials.GOLD) || material.equals(ArmorMaterials.NETHERITE);
			}).build();

	public MidasTouchstoneItem() {
		super(new Properties().stacksTo(1).rarity(Rarity.EPIC));
	}

	@Override
	protected void addMoreInformation(ItemStack touchstone, @Nullable HolderLookup.Provider registries, TooltipBuilder tooltipBuilder) {
		tooltipBuilder.charge(this, ".tooltip2", getTotalGlowstoneCharge(touchstone));
		if (isEnabled(touchstone)) {
			tooltipBuilder.absorbActive(Items.GLOWSTONE_DUST.getName(new ItemStack(Items.GLOWSTONE_DUST)).getString());
		} else {
			tooltipBuilder.absorb();
		}
	}

	@Override
	protected boolean hasMoreInformation(ItemStack stack) {
		return true;
	}

	@Override
	public void inventoryTick(ItemStack stack, Level level, Entity entity, int i, boolean f) {
		if (level.isClientSide || !(entity instanceof Player player) || player.isSpectator() || level.getGameTime() % 10 != 0) {
			return;
		}

		// TODO legacy support, remove in future
		if (!stack.has(ModDataComponents.PARTIAL_CHARGES)) {
			getMigratedStoredCharge(stack, FIRST_SLOT);
		}

		if (isEnabled(stack)) {
			int freeGlowstoneCapacity = Math.max(getGlowstoneLimit() - getTotalGlowstoneCharge(stack), 0) / getGlowStoneWorth();
			consumeAndCharge(stack, 0, player, freeGlowstoneCapacity, 1, 16);
		}

		doRepairAndDamageTouchstone(stack, player);
	}

	@Override
	protected boolean isItemValidForContainerSlot(ItemStack containerStack, int slot, ItemStack stack) {
		return stack.is(Items.GLOWSTONE_DUST);
	}

	public static int getGlowstoneCharge(ItemStack stack) {
		return stack.getOrDefault(ModDataComponents.GLOWSTONE, 0);
	}

	public static int getTotalGlowstoneCharge(ItemStack stack) {
		return ((MidasTouchstoneItem) stack.getItem()).getTotalCharge(stack);
	}

	private void doRepairAndDamageTouchstone(ItemStack touchstone, Player player) {
		List<String> goldItems = Config.COMMON.items.midasTouchstone.getGoldItems();

		IItemHandler playerInventory = InventoryHelper.getItemHandlerFrom(player);
		if (playerInventory == null) {
			return;
		}
		for (int slot = 0; slot < playerInventory.getSlots(); slot++) {
			ItemStack stack = playerInventory.getStackInSlot(slot);
			Item item = stack.getItem();

			if (stack.getDamageValue() <= 0 || !stack.has(DataComponents.DAMAGE)) {
				continue;
			}

			tryRepairingItem(touchstone, player, goldItems, stack, item);
		}
	}

	private void tryRepairingItem(ItemStack touchstone, Player player, List<String> goldItems, ItemStack stack, Item item) {
		Optional<IRepairableItem> repairableItem = getRepairableItem(item.getClass());
		if ((repairableItem.isPresent() && repairableItem.get().materialMatches(item)) || goldItems.contains(RegistryHelper.getItemRegistryName(item))) {
			repairItem(stack, touchstone, player);
		}
	}

	private void repairItem(ItemStack stack, ItemStack touchstone, Player player) {
		if (reduceTouchStoneCharge(touchstone, player)) {
			int damage = stack.getDamageValue();
			stack.setDamageValue(damage - Math.min(damage, 10));
		}
	}

	private boolean reduceTouchStoneCharge(ItemStack stack, Player player) {
		return player.isCreative() || useCharge(stack, getGlowStoneCost());
	}

	private int getGlowStoneCost() {
		return Config.COMMON.items.midasTouchstone.glowstoneCost.get();
	}

	private int getGlowStoneWorth() {
		return Config.COMMON.items.midasTouchstone.glowstoneWorth.get();
	}

	private int getGlowstoneLimit() {
		return Config.COMMON.items.midasTouchstone.glowstoneLimit.get();
	}

	private Optional<IRepairableItem> getRepairableItem(Class<? extends Item> item) {
		for (Map.Entry<Class<? extends Item>, IRepairableItem> repairableItem : REPAIRABLE_ITEMS.entrySet()) {
			if (repairableItem.getKey().isAssignableFrom(item)) {
				return Optional.of(repairableItem.getValue());
			}
		}
		return Optional.empty();
	}

	@Override
	public Type getCuriosType() {
		return Type.CHARM;
	}

	@Override
	public void onWornTick(ItemStack stack, LivingEntity player) {
		inventoryTick(stack, player.level(), player, 0, false);
	}

	@Override
	public void addStoredCharge(ItemStack containerStack, int slot, int chargeToAdd, @Nullable ItemStack chargeStack) {
		containerStack.set(ModDataComponents.GLOWSTONE, Math.max(getGlowstoneCharge(containerStack) + chargeToAdd, 0));
	}

	@Override
	protected int getSlotWorth(int slot) {
		return slot == 0 ? getGlowStoneWorth() : 0;
	}

	@Override
	public int getStoredCharge(ItemStack containerStack, int slot) {
		return getGlowstoneCharge(containerStack);
	}

	private interface IRepairableItem {
		boolean materialMatches(Item item);
	}
}

package reliquary.item.util.fluid;

import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.fluids.FluidStack;
import net.neoforged.neoforge.fluids.capability.IFluidHandlerItem;
import reliquary.init.ModFluids;
import reliquary.init.ModItems;
import reliquary.util.XpHelper;

public class FluidHandlerHeroMedallion implements IFluidHandlerItem {
	private static final int MAX_CAPACITY = Integer.MAX_VALUE;
	private final ItemStack heroMedallion;

	public FluidHandlerHeroMedallion(ItemStack heroMedallion) {
		this.heroMedallion = heroMedallion;
	}

	@Override
	public ItemStack getContainer() {
		return heroMedallion;
	}

	@Override
	public int getTanks() {
		return 1;
	}

	@Override
	public FluidStack getFluidInTank(int tank) {
		return new FluidStack(ModFluids.XP_STILL.get(), XpHelper.experienceToLiquid(getMedallionXp()));
	}

	@Override
	public int getTankCapacity(int tank) {
		return MAX_CAPACITY;
	}

	@Override
	public boolean isFluidValid(int tank, FluidStack stack) {
		return tank == 0 && isXpJuiceFluid(stack);
	}

	private boolean isXpJuiceFluid(FluidStack stack) {
		return stack.getFluid().is(ModFluids.EXPERIENCE_TAG);
	}

	@Override
	public int fill(FluidStack resource, FluidAction action) {
		if (!isXpJuiceFluid(resource)) {
			return 0;
		}

		int currentXp = getMedallionXp();
		int toFill = Math.min(MAX_CAPACITY - XpHelper.experienceToLiquid(currentXp), resource.getAmount());

		if (action == FluidAction.EXECUTE) {
			ModItems.HERO_MEDALLION.get().setExperience(heroMedallion, currentXp + XpHelper.liquidToExperience(toFill));
		}

		return toFill;
	}

	private int getMedallionXp() {
		return ModItems.HERO_MEDALLION.get().getExperience(heroMedallion);
	}

	@Override
	public FluidStack drain(FluidStack resource, FluidAction action) {
		if (!isXpJuiceFluid(resource)) {
			return FluidStack.EMPTY;
		}

		int currentXp = getMedallionXp();
		int currentLiquidXp = XpHelper.experienceToLiquid(currentXp);
		int toDrain = Math.min(currentLiquidXp, resource.getAmount());

		if (action == FluidAction.EXECUTE) {
			ModItems.HERO_MEDALLION.get().setExperience(heroMedallion, currentXp - XpHelper.liquidToExperience(toDrain));
		}

		return new FluidStack(resource.getFluid(), toDrain);
	}

	@Override
	public FluidStack drain(int maxDrain, FluidAction action) {
		return drain(new FluidStack(ModFluids.XP_STILL.get(), maxDrain), action);
	}
}

